## בעיית סגנון 1: שמות פונקציות גרועים
{{CONTEXT_STYLE_1_NARRATIVE}}

def greet(x):
    return f"Hello, {x}!"

def calculate(a, b, c):
    return (a + b) * c

print(greet("{{hero}}"))
print(calculate(10, 5, 2))

def do_stuff(thing):
    return thing.upper()

def process(data):
    return len(data)

def handle(items):
    return items[0]

text = "{{hero}}"
result1 = do_stuff(text)
result2 = process(text)
result3 = handle([1, 2, 3])
print(f"{result1}, {result2}, {result3}")

def f1(n, m="{{school}}"):
    return f"{n} from {m}"

def f2(x, y, z=1):
    return (x + y) * z

def Thing(A):
    if A > 10:
        return "high"
    return "low"

print(f1("{{hero}}"))
print(f2(5, 3, 2))
print(Thing(15))

