def get_status(level):
    if level >= 10:
        return "Expert"
    return "Novice"

status = get_status(15)
print(f"Status: {status}")

def get_status(level):
    if level >= 10:
        print("Expert")
    print("Novice")

status = get_status(15)
print(f"Status: {status}")

def double(n):
    return n * 2

def add_five(n):
    return n + 5

result = add_five(double(10))
print(f"Result: {result}")

def double(n):
    print(n * 2)

def add_five(n):
    return n + 5

result = add_five(double(10))  # double returns None!
print(f"Result: {result}")

